// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(this), fundAmount);
        if (fundAmount > 0) {
            (bool s, ) = address(c).call{value: fundAmount}("");
            require(s);
        }

        bool ok;
        try c.withdrawAll(address(rev)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (address(c).balance > 0) {
            assertTrue(!ok);
        } else {
            assertTrue(true);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
